function validate([capacity, rocks, additionalRocks]) {
  if (capacity.length < 1 || capacity.length > 50000) return 'capacity needs 1 to 50000 values.';
  if (rocks.length !== capacity.length) return 'capacity and rocks must have the same length.';
  if (capacity.some(c => !Number.isInteger(c) || c < 1 || c > 1e9)) return 'Each capacity is between 1 and 10^9.';
  if (rocks.some((r, i) => !Number.isInteger(r) || r < 0 || r > capacity[i])) return 'Each rocks[i] is between 0 and capacity[i].';
  if (!Number.isInteger(additionalRocks) || additionalRocks < 1 || additionalRocks > 1e9) return 'additionalRocks is between 1 and 10^9.';
  return null;
}

