function maximumBags(capacity, rocks, additionalRocks) {
  const missing = capacity.map((cap, i) => cap - rocks[i]);
  missing.sort((a, b) => a - b);
  let remaining = additionalRocks;
  let full = 0;

  for (const need of missing) {
    if (need > remaining) {
      break;
    }
    remaining -= need;
    full++;
  }
  return full;
}

