function maximumBags(capacity, rocks, additionalRocks) {
  const n = capacity.length;
  let best = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let cost = 0, count = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) { cost += capacity[i] - rocks[i]; count++; }
    }
    if (cost <= additionalRocks && count > best) best = count;
  }
  return best;
}

