function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const top = rand() < 0.5 ? 1e9 : int(1, 1e6);
    const capacity = Array.from({ length: n }, () => int(1, top));
    const rocks = capacity.map(cap => rand() < 0.2 ? cap : int(0, cap));
    let total = 0;
    for (let i = 0; i < n; i++) total += capacity[i] - rocks[i];
    const additionalRocks = Math.max(1, Math.min(1e9, Math.floor(total * rand() * 0.3)));
    return [capacity, rocks, additionalRocks];
  }
  const n = int(1, 9);
  const top = int(1, 12);
  const capacity = Array.from({ length: n }, () => int(1, top));
  const rocks = capacity.map(cap => rand() < 0.25 ? cap : int(0, cap));
  const additionalRocks = int(1, 3 * top);
  return [capacity, rocks, additionalRocks];
}
